import Foundation
import Testing

@testable import Decimal128TextCodec

/// The four conformance tables, over the shared `string_bid_dpd` corpus.
///
/// The vectors are vendored under `Tests/Decimal128TextCodecTests/vectors` from
/// `decimal128-text-codec-c/tests/vectors`, which is this family's corpus of
/// record, and were generated by the `decimal128-c` engine through its public
/// API. That engine reaches its answers by different algorithms than this codec
/// does, so agreement is a cross-check rather than a tautology.
///
///   T1 DECODE  bid → text and dpd → text          (100, noncanonical)
///   T2 ENCODE  text → bid and text → dpd          (100)
///   T3 PARSE   input text → bits, both formats    (parse, 945 rows)
///   T4 ERROR   malformed input text → rejection   (error, 133 rows)
///
/// Plus the cross-format assertion: for every row both encodings must render to
/// the same text. That is the strongest property the corpus encodes.
///
/// The `canonical` table (84,764 rows) is not vendored — at this density it
/// would be some 10 MB. `TestCanonicalCorpus` runs it when a sibling
/// `decimal128-resources` checkout is present.
@Suite
struct TestCorpusVectors {

    /// Every row: both encodings must render to the expected text, and
    /// therefore to each other.
    static func runDecodeTable(_ rows: [CorpusRow], _ label: String) {
        for row in rows {
            let bidText = Decimal128TextCodec.bid128ToString(row.bid)
            let dpdText = Decimal128TextCodec.dpd128ToString(row.dpd)
            #expect(bidText == row.text,
                    "\(label) line \(row.lineNumber): bid \(Hex.format32(row.bid)) rendered <\(bidText)>")
            #expect(dpdText == row.text,
                    "\(label) line \(row.lineNumber): dpd \(Hex.format32(row.dpd)) rendered <\(dpdText)>")
        }
    }

    /// Round-trippable rows: the text must encode back to the same bits.
    static func runEncodeTable(_ rows: [CorpusRow], _ label: String) {
        for row in rows {
            let b = bidParse(row.text)
            #expect(b.error == nil,
                    "\(label) line \(row.lineNumber): bid rejected <\(row.text)>: \(b.error ?? "")")
            if b.error == nil {
                #expect(b.bits == row.bid,
                        "\(label) line \(row.lineNumber): bid <\(row.text)> gave \(Hex.format32(b.bits))")
            }
            let d = dpdParse(row.text)
            #expect(d.error == nil,
                    "\(label) line \(row.lineNumber): dpd rejected <\(row.text)>: \(d.error ?? "")")
            if d.error == nil {
                #expect(d.bits == row.dpd,
                        "\(label) line \(row.lineNumber): dpd <\(row.text)> gave \(Hex.format32(d.bits))")
            }
        }
    }

    @Test("T1/T2: the 100-value table decodes and re-encodes")
    func hundred() throws {
        let rows = try Corpus.load(Corpus.hundred)
        #expect(rows.count == 100)
        Self.runDecodeTable(rows, "100")
        Self.runEncodeTable(rows, "100")
    }

    /// One-way rows: both encodings decode to the text, but at least one is a
    /// bit pattern the canonical encoder would never emit, so re-encoding is
    /// deliberately not asserted.
    @Test("T1: non-canonical encodings render as their canonical spelling")
    func nonCanonical() throws {
        let rows = try Corpus.load(Corpus.nonCanonical)
        #expect(rows.count == 1262)
        Self.runDecodeTable(rows, "noncanonical")
    }

    /// The only table that reaches the rounding surface at all.
    @Test("T3: input text parses to the expected bits in both formats")
    func parse() throws {
        let rows = try Corpus.load(Corpus.parse)
        #expect(rows.count == 945)
        for row in rows {
            let b = bidParse(row.text)
            #expect(b.error == nil, "parse line \(row.lineNumber): bid rejected <\(row.text)>: \(b.error ?? "")")
            if b.error == nil {
                #expect(b.bits == row.bid,
                        "parse line \(row.lineNumber): bid <\(row.text)> gave \(Hex.format32(b.bits))")
            }
            let d = dpdParse(row.text)
            #expect(d.error == nil, "parse line \(row.lineNumber): dpd rejected <\(row.text)>: \(d.error ?? "")")
            if d.error == nil {
                #expect(d.bits == row.dpd,
                        "parse line \(row.lineNumber): dpd <\(row.text)> gave \(Hex.format32(d.bits))")
            }
        }
    }

    /// Malformed input. Both formats must reject, must agree on the message,
    /// and must still have written the canonical positive quiet NaN — the
    /// corpus carries that pattern in its bits columns precisely so a port can
    /// assert the written value and not merely the rejection.
    ///
    /// This table is the family's corpus of record rather than upstream: it
    /// carries 133 rows where `decimal128-resources` has 135. `"NaN(1)"` and
    /// `"NaN(123)"` assert a rejection the codecs no longer perform.
    @Test("T4: malformed input is rejected identically by both formats")
    func error() throws {
        let rows = try Corpus.load(Corpus.error)
        #expect(rows.count == 133)
        for row in rows {
            let b = bidParse(row.text)
            let d = dpdParse(row.text)
            #expect(b.error != nil, "error line \(row.lineNumber): bid ACCEPTED <\(row.text)>, corpus says \(row.status)")
            #expect(d.error != nil, "error line \(row.lineNumber): dpd ACCEPTED <\(row.text)>, corpus says \(row.status)")
            if b.error != nil && d.error != nil {
                #expect(b.error == d.error,
                        "error line \(row.lineNumber): the formats disagree on <\(row.text)>")
            }
            #expect(b.bits == row.bid, "error line \(row.lineNumber): bid <\(row.text)> left \(Hex.format32(b.bits))")
            #expect(d.bits == row.bid, "error line \(row.lineNumber): dpd <\(row.text)> left \(Hex.format32(d.bits))")
        }
    }

    /// The reader itself. `parse` and `error` quote their text column, and the
    /// four rows below are exactly the ones a naive comma split corrupts while
    /// still passing — a mangled malformed input fails to parse either way.
    @Test("the quoted text column survives the reader")
    func quotedColumnRoundTrips() throws {
        let rows = try Corpus.load(Corpus.error)
        let texts = Set(rows.map(\.text))
        #expect(texts.contains(""), "the empty-string row was lost")
        #expect(texts.contains(where: { $0.hasPrefix(" ") }), "a leading-space row was lost")
        #expect(texts.contains(where: { $0.hasSuffix(" ") }), "a trailing-space row was lost")
        #expect(texts.contains(where: { $0.contains(",") }), "an embedded-comma row was lost")
    }
}

/// The full canonical table, when a sibling `decimal128-resources` checkout is
/// present. 84,764 rows, not vendored: at this density it is some 10 MB.
@Suite
struct TestCanonicalCorpus {

    static var canonicalPath: String? {
        // Tests run from the build directory, so walk up from this file.
        let here = URL(fileURLWithPath: #filePath)
        let repoRoot = here.deletingLastPathComponent()  // Decimal128TextCodecTests
            .deletingLastPathComponent()                 // Tests
            .deletingLastPathComponent()                 // repo root
        let path = repoRoot
            .deletingLastPathComponent()
            .appendingPathComponent("decimal128-resources/string_bid_dpd/string_bid128_dpd128_canonical.csv.txt")
            .path
        return FileManager.default.fileExists(atPath: path) ? path : nil
    }

    @Test("the 84,764-row canonical table, when a sibling checkout is present")
    func canonical() throws {
        guard let path = Self.canonicalPath else {
            print("canonical table: skipped, no sibling decimal128-resources checkout")
            return
        }
        let rows = try Corpus.loadFile(path)
        #expect(rows.count == 84764)
        TestCorpusVectors.runDecodeTable(rows, "canonical")
        TestCorpusVectors.runEncodeTable(rows, "canonical")
    }
}
